class Buffer {
    int* data;
    size_t size;
public:
    Buffer(size_t s) : size(s), data(new int[s]{}) {
        std::cout << "Allocated buffer of size " << size << "\n";
    }
    ~Buffer() {
        delete[] data;
        std::cout << "Freed buffer\n";
    }
    // Move Constructor
    Buffer(Buffer&& other) noexcept : data(other.data), size(other.size) {
        other.data = nullptr;
        other.size = 0;
        std::cout << "Moved buffer\n";
    }
};

int main() {
    std::cout << "=== 02: RAII & Move ===\n";
    Buffer b1(1024);
    Buffer b2 = std::move(b1);
    return 0;
}

