#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>

template <typename T>
class ThreadSafeQueue {
    std::queue<T> q;
    mutable std::mutex mtx;
    std::condition_variable cv;
public:
    void push(T val) {
        std::lock_guard<std::mutex> lock(mtx);
        q.push(std::move(val));
        cv.notify_one();
    }
    T pop() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !q.empty(); });
        T val = std::move(q.front());
        q.pop();
        return val;
    }
};

int main() {
    ThreadSafeQueue<int> q;
    q.push(42);
    std::cout << "Popped value: " << q.pop() << "\n";
    std::cout << "✔ ThreadSafeQueue drill passed!\n";
    return 0;
}
